class IPAddress:
    OCTET_COUNT = 4
    OCTET_MIN_VALUE = 0
    OCTET_MAX_VALUE = 255
    BINARY_OCTET_LENGTH = 8
    DOT = '.'
    EMPTY_STRING = ''

    def __init__(self, ip_address):
        self._ip_address = ip_address

    @property
    def ip_address(self):
        return self._ip_address

    @ip_address.setter
    def ip_address(self, value):
        self._ip_address = value

    def is_valid(self):
        octets = self._get_octets()
        if len(octets) != self.OCTET_COUNT:
            return False
        return all(self._is_valid_octet(octet) for octet in octets)

    def _get_octets(self):
        return self.ip_address.split(self.DOT)

    def _is_valid_octet(self, octet):
        return octet.isdigit() and self.OCTET_MIN_VALUE <= int(octet) <= self.OCTET_MAX_VALUE

    def get_octets(self):
        return self._get_octets() if self.is_valid() else []

    def get_binary(self):
        if not self.is_valid():
            return self.EMPTY_STRING
        octets = self.get_octets()
        binary_octets = [self._octet_to_binary(octet) for octet in octets]
        return self.DOT.join(binary_octets)

    def _octet_to_binary(self, octet):
        return format(int(octet), f'0{self.BINARY_OCTET_LENGTH}b')
